ALTER TABLE public.fc_world_rooms ADD COLUMN region_depth text NOT NULL DEFAULT 'city';
UPDATE public.fc_world_rooms SET region_depth=CASE WHEN kind='forest' AND name LIKE '%外围%' THEN 'outer' WHEN kind='forest' THEN 'inner' WHEN kind='wilderness' THEN 'outer' ELSE 'city' END;
CREATE TABLE public.fc_monster_definitions(id text PRIMARY KEY,name text NOT NULL,realm_index smallint NOT NULL,region_depth text NOT NULL,base_health numeric NOT NULL,base_attack numeric NOT NULL,base_defense numeric NOT NULL,speed numeric NOT NULL,weakness text NOT NULL,combat_note text NOT NULL,image_path text);
CREATE TABLE public.fc_combat_encounters(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),character_id uuid NOT NULL REFERENCES public.fc_characters(id),room_id uuid NOT NULL REFERENCES public.fc_world_rooms(id),monster_id text NOT NULL REFERENCES public.fc_monster_definitions(id),monster_count smallint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),status text NOT NULL DEFAULT 'active',player_health numeric NOT NULL,monster_health numeric NOT NULL,turn integer NOT NULL DEFAULT 0,result text);
ALTER TABLE public.fc_monster_definitions ENABLE ROW LEVEL SECURITY; ALTER TABLE public.fc_combat_encounters ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.fc_monster_definitions,public.fc_combat_encounters FROM anon,authenticated;
