CREATE FUNCTION public.fc_get_combat() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c public.fc_characters; e public.fc_combat_encounters; m public.fc_monster_definitions;
BEGIN SELECT * INTO c FROM public.fc_characters WHERE owner_id=public.fc_require_uid(); SELECT * INTO e FROM public.fc_combat_encounters WHERE character_id=c.id AND status='active' LIMIT 1; IF e.id IS NULL THEN RETURN jsonb_build_object('active',false); END IF; SELECT * INTO m FROM public.fc_monster_definitions WHERE id=e.monster_id; RETURN jsonb_build_object('active',true,'encounter',to_jsonb(e),'monster',to_jsonb(m),'player_realm',c.realm,'player_name',c.display_name,'player_avatar_key',c.avatar_key); END $$;
CREATE FUNCTION public.fc_use_lure() RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c public.fc_characters; p public.fc_character_positions; cell public.fc_world_cells; r public.fc_world_rooms; item public.fc_inventory_slots;
BEGIN SELECT * INTO c FROM public.fc_characters WHERE owner_id=public.fc_require_uid() FOR UPDATE; SELECT * INTO p FROM public.fc_character_positions WHERE character_id=c.id; SELECT * INTO cell FROM public.fc_world_cells WHERE id=p.cell_id; SELECT * INTO r FROM public.fc_world_rooms WHERE id=cell.room_id; IF r.kind NOT IN ('wilderness','forest','road') THEN RAISE EXCEPTION '只能在野外或官道使用引妖散'; END IF; SELECT * INTO item FROM public.fc_inventory_slots WHERE character_id=c.id AND item_key='lure_powder' ORDER BY slot LIMIT 1 FOR UPDATE; IF item.slot IS NULL THEN RAISE EXCEPTION '没有引妖散'; END IF; IF item.quantity=1 THEN DELETE FROM public.fc_inventory_slots WHERE character_id=c.id AND slot=item.slot; ELSE UPDATE public.fc_inventory_slots SET quantity=quantity-1 WHERE character_id=c.id AND slot=item.slot; END IF; UPDATE public.fc_world_rooms SET encounter_rate=1 WHERE id=r.id; RETURN jsonb_build_object('message','引妖散生效：当前区域遇怪概率提升至100%，下一次判定必定遇怪。'); END $$;
CREATE FUNCTION public.fc_spawn_combat() RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c public.fc_characters; p public.fc_character_positions; cell public.fc_world_cells; r public.fc_world_rooms; m public.fc_monster_definitions; e public.fc_combat_encounters; chance numeric; allowed integer;
BEGIN SELECT * INTO c FROM public.fc_characters WHERE owner_id=public.fc_require_uid() FOR UPDATE; SELECT * INTO p FROM public.fc_character_positions WHERE character_id=c.id; SELECT * INTO cell FROM public.fc_world_cells WHERE id=p.cell_id; SELECT * INTO r FROM public.fc_world_rooms WHERE id=cell.room_id; IF r.kind NOT IN ('wilderness','forest','road') THEN RETURN public.fc_get_combat(); END IF; SELECT * INTO e FROM public.fc_combat_encounters WHERE character_id=c.id AND status='active' LIMIT 1; IF e.id IS NOT NULL THEN RETURN public.fc_get_combat(); END IF; IF random()>r.encounter_rate THEN RETURN jsonb_build_object('active',false); END IF; allowed:=CASE WHEN r.region_depth='outer' THEN least(1,c.realm_index+1) WHEN r.region_depth='inner' THEN least(2,c.realm_index+1) ELSE 2 END; SELECT * INTO m FROM public.fc_monster_definitions WHERE region_depth=r.region_depth AND realm_index<=allowed ORDER BY random() LIMIT 1; IF m.id IS NULL THEN RETURN jsonb_build_object('active',false); END IF; INSERT INTO public.fc_combat_encounters(character_id,room_id,monster_id,monster_count,player_health,monster_health) VALUES(c.id,r.id,m.id,1+floor(random()*3)::int,(public.fc_get_attributes()->>'health')::numeric,m.base_health) RETURNING * INTO e; RETURN public.fc_get_combat(); END $$;
CREATE FUNCTION public.fc_resolve_combat(p_action text DEFAULT 'auto') RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c public.fc_characters; e public.fc_combat_encounters; m public.fc_monster_definitions; a numeric; damage numeric; md numeric; win boolean;
BEGIN SELECT * INTO c FROM public.fc_characters WHERE owner_id=public.fc_require_uid() FOR UPDATE; SELECT * INTO e FROM public.fc_combat_encounters WHERE character_id=c.id AND status='active' LIMIT 1; IF e.id IS NULL THEN RETURN public.fc_get_combat(); END IF; SELECT * INTO m FROM public.fc_monster_definitions WHERE id=e.monster_id; a:=(public.fc_get_attributes()->>'attack')::numeric; damage:=greatest(1,a-m.base_defense*.35); md:=greatest(1,m.base_attack-(public.fc_get_attributes()->>'defense')::numeric*.25); UPDATE public.fc_combat_encounters SET turn=turn+1,player_health=player_health-md,monster_health=monster_health-damage WHERE id=e.id RETURNING * INTO e; IF e.monster_health<=0 THEN UPDATE public.fc_combat_encounters SET status='won',result='胜利' WHERE id=e.id; ELSIF e.player_health<=0 THEN UPDATE public.fc_combat_encounters SET status='lost',result='战败' WHERE id=e.id; END IF; RETURN public.fc_get_combat(); END $$;
REVOKE ALL ON FUNCTION public.fc_get_combat(),public.fc_use_lure(),public.fc_spawn_combat(),public.fc_resolve_combat(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.fc_get_combat(),public.fc_use_lure(),public.fc_spawn_combat(),public.fc_resolve_combat(text) TO authenticated;
